mapper.select:
SELECT t.task_id, t.task_name, t.priority_id, p.priority_name, t.category_id, c.category_name, t.scheduled_work_date, t.parent_id, t.memo, t.done_flg FROM item_table t LEFT JOIN priority_deta p ON t.priority_id = p.priority_id LEFT JOIN category_deta c ON t.category_id = c.category_id
AND t.task_name LIKE CONCAT( '%', REPLACE( REPLACE( REPLACE( #{taskName},'\','\\'), '%','\%' ), '_','\_' ), '%' )ESCAPE '\'
AND t.scheduled_work_date>= #{fromDate}
AND t.scheduled_work_date<= #{toDate}
AND t.done_flg = #{doneFlg}
AND t.priority_id = #{priorityId}
AND t.category_id = #{categoryId}
ORDER BY COALESCE(t.parent_id,t.task_id), t.parent_id NULLS FIRST, t.task_id
